use gpui::{div, px, IntoElement, ParentElement, Styled};

pub enum RunState {
    Running,
    Passed,
}

pub struct Run {
    pub name: String,
    pub took: String,
    pub state: RunState,
}

fn mark(state: &RunState) -> impl IntoElement {
    let colour = match state {
        RunState::Running => gpui::rgb(0xffca85),
        RunState::Passed => gpui::rgb(0x61ffca),
    };
    div().size(px(12.0)).rounded_full().border_2().border_color(colour)
}

pub fn popover(runs: &[Run]) -> impl IntoElement {
    div().w(px(320.0)).p(px(8.0)).rounded_md().children(runs.iter().map(|run| {
        div()
            .flex()
            .items_center()
            .gap(px(8.0))
            .h(px(28.0))
            .px(px(8.0))
            .child(mark(&run.state))
            .child(div().flex_1().child(run.name.clone()))
            .child(div().text_xs().child(run.took.clone()))
    }))
}

