import { useEffect, useRef, useState } from 'react';
import { loadOlder, type Post } from '../api/posts';

export function Feed({ initial }: { initial: Post[] }) {
  const [posts, setPosts] = useState(initial);
  const list = useRef<HTMLDivElement>(null);

  async function onScroll() {
    const element = list.current!;
    if (element.scrollTop > 200) return;
    const older = await loadOlder(posts[0].id);
    console.debug('[feed] prepend', older.length, 'scrollTop', element.scrollTop, 'height', element.scrollHeight);
    setPosts((current) => [...older, ...current]);
  }

  useEffect(() => {
    const element = list.current!;
    console.debug('[feed] rendered scrollTop', element.scrollTop, 'height', element.scrollHeight);
  }, [posts]);

  return (
    <div ref={list} className="feed" style={{ overflowAnchor: 'auto' }} onScroll={onScroll}>
      {posts.map((post) => (
        <article key={post.id}>{post.text}</article>
      ))}
    </div>
  );
}

